import re
import sys

ERROR_RE = re.compile(r"^(\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}) ERROR \[([^\]]+)\] (.*)$")


def parse_errors(path):
    rows = []
    with open(path, encoding="utf-8") as f:
        for line in f:
            m = ERROR_RE.match(line.rstrip("\r\n"))
            if m:
                rows.append({"time": m.group(1), "module": m.group(2), "message": m.group(3)})
    return rows


def format_table(rows):
    lines = ["| time | module | message |", "|---|---|---|"]
    for r in rows:
        cells = [r["time"], r["module"], r["message"]]
        lines.append("| " + " | ".join(c.replace("|", "\\|") for c in cells) + " |")
    return "\n".join(lines)


if __name__ == "__main__":
    if len(sys.argv) != 2:
        sys.exit("usage: python parse.py <logfile>")
    sys.stdout.reconfigure(encoding="utf-8")
    print(format_table(parse_errors(sys.argv[1])))

